class Box {
	constructor(xMin, yMin, zMin, xMax, yMax, zMax, showArray) {
		this.showArray = showArray;
		this.v = [];
		this.v.push(new p5.Vector(xMin,yMin,zMin));
		this.v.push(new p5.Vector(xMax,yMin,zMin));
		this.v.push(new p5.Vector(xMax,yMax,zMin));
		this.v.push(new p5.Vector(xMin,yMax,zMin));
		this.v.push(new p5.Vector(xMin,yMin,zMax));
		this.v.push(new p5.Vector(xMax,yMin,zMax));
		this.v.push(new p5.Vector(xMax,yMax,zMax));
		this.v.push(new p5.Vector(xMin,yMax,zMax));
	}

	show(angle, topAngle, cityShadedPalette, chosenColorIndex) {
		if (angle > 0) {
			if (this.showArray[0]) {// wall xMin
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][0]);
				transformVectorQuad(this.v[0], this.v[3], this.v[7], this.v[4], angle, topAngle);
			}
		} else {
			if (this.showArray[1]) {// wall xMax
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][1]);
				transformVectorQuad(this.v[1], this.v[2], this.v[6], this.v[5], angle, topAngle);
			}
		}
		if (angle < -90 || angle > 90) {
			if (this.showArray[2]) {// wall yMin
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][2]);
				transformVectorQuad(this.v[0], this.v[1], this.v[5], this.v[4], angle, topAngle);
			}
		} else {
			if (this.showArray[3]) {// wall yMax
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][3]);
				transformVectorQuad(this.v[2], this.v[3], this.v[7], this.v[6], angle, topAngle);
			}
		}
		if (topAngle < 0) {
			if (this.showArray[4]) {// bottom zMin
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][4]);
				transformVectorQuad(this.v[0], this.v[1], this.v[2], this.v[3], angle, topAngle);
			}
		} else {
			if (this.showArray[5]) {// top zMax
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][5]);
				transformVectorQuad(this.v[4], this.v[5], this.v[6], this.v[7], angle, topAngle);
			}
		}
	}

	showInverse(angle, topAngle, cityShadedPalette, chosenColorIndex) {
		if (angle < 0) {
			if (this.showArray[0]) {// wall xMin
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][1]);
				transformVectorQuad(this.v[0], this.v[3], this.v[7], this.v[4], angle, topAngle);}
		} else {
			if (this.showArray[1]) {// wall xMax
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][0]);
				transformVectorQuad(this.v[1], this.v[2], this.v[6], this.v[5], angle, topAngle);}
		}
		if (angle > -90 && angle < 90) {
			if (this.showArray[2]) {// wall yMin
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][3]);
				transformVectorQuad(this.v[0], this.v[1], this.v[5], this.v[4], angle, topAngle);}
		} else {
			if (this.showArray[3]) {// wall yMax
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][2]);
				transformVectorQuad(this.v[2], this.v[3], this.v[7], this.v[6], angle, topAngle);}
		}
		if (topAngle > 0) {
			if (this.showArray[4]) {
				// bottom zMin
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][5]);
				transformVectorQuad(this.v[0], this.v[1], this.v[2], this.v[3], angle, topAngle);}
		} else {
			if (this.showArray[5]) {// top zMax
				setStrokeAndFill(cityShadedPalette[chosenColorIndex][4]);
				transformVectorQuad(this.v[4], this.v[5], this.v[6], this.v[7], angle, topAngle);}
		}
	}
}



