function setStrokeAndFill(c) {
	stroke(c);
	fill(c);
}

function vectorVertex(a) {
	vertex(a.x, b.x);
}

function transformVectorVertex(a, angle, topAngle) {
	vertex(
		a.x*cos(angle) + a.y*sin(angle),
		cos(topAngle) * (-a.x*sin(angle)+a.y*cos(angle)) - a.z*sin(topAngle));
}

function vectorLine(a, b) {
	line(a.x, a.y, b.x, b.y);
}

function vectorQuad(a, b, c, d) {
	quad(a.x, a.y, b.x, b.y, c.x, c.y, d.x, d.y);
}

function transformVectorQuad(a, b, c, d, angle, topAngle) {
	quad(
		a.x*cos(angle) +a.y*sin(angle),
		cos(topAngle)*(-a.x*sin(angle) +a.y*cos(angle)) -a.z*sin(topAngle),
		b.x*cos(angle) +b.y*sin(angle),
		cos(topAngle)*(-b.x*sin(angle) +b.y*cos(angle)) -b.z*sin(topAngle),
		c.x*cos(angle) +c.y*sin(angle),
		cos(topAngle)*(-c.x*sin(angle) +c.y*cos(angle)) -c.z*sin(topAngle),
		d.x*cos(angle) +d.y*sin(angle),
		cos(topAngle)*(-d.x*sin(angle) +d.y*cos(angle)) -d.z*sin(topAngle));
}

function overlayColors(a,b,opacity) {
	let overlay = color(
		(  red(window.color(a)) < 128)? 2*  red(window.color(a))*  red(window.color(b))/255: 255 - 2*(255-  red(window.color(a)))*(255-  red(window.color(b)))/255,
		(green(window.color(a)) < 128)? 2*green(window.color(a))*green(window.color(b))/255: 255 - 2*(255-green(window.color(a)))*(255-green(window.color(b)))/255,
		( blue(window.color(a)) < 128)? 2* blue(window.color(a))* blue(window.color(b))/255: 255 - 2*(255- blue(window.color(a)))*(255- blue(window.color(b)))/255,
	);
	if (!opacity) return overlay; else return lerpColor(a,overlay,opacity);
}

function addColors(a,b,factor1,factor2) {
	return color(
		  red(window.color(a))*factor1+  red(window.color(b))*factor2,
		green(window.color(a))*factor1+green(window.color(b))*factor2,
		 blue(window.color(a))*factor1+ blue(window.color(b))*factor2);
}

function subColors(a,b,factor1,factor2) {
	return color(
		  red(window.color(a))*factor1-  red(window.color(b))*factor2,
		green(window.color(a))*factor1-green(window.color(b))*factor2,
		 blue(window.color(a))*factor1- blue(window.color(b))*factor2);
}

function multColors(a,b, opacity) {
	//let s = c1*map(opacity,0,1,1,c2/255);
	let mult = color(
		  red(window.color(a))*  red(window.color(b))/255,
		green(window.color(a))*green(window.color(b))/255,
		 blue(window.color(a))* blue(window.color(b))/255);
	if (!opacity) return mult; else return lerpColor(a,mult,opacity);
}

function screenColors(a,b,opacity) {
	//let s = 255-(255-c1)*map(opacity,0,1,1,1-c2/255);
	let screen = color(
		255-(255-  red(window.color(a)))*(255-  red(window.color(b)))/255,
		255-(255-green(window.color(a)))*(255-green(window.color(b)))/255,
		255-(255- blue(window.color(a)))*(255- blue(window.color(b)))/255);
	if (!opacity) return screen; else return lerpColor(a,screen,opacity);
}

function minColors(a,b,opacity) {
	if (!opacity) return color(
		min(  red(window.color(a)),  red(window.color(b))),
		min(green(window.color(a)),green(window.color(b))),
		min( blue(window.color(a)), blue(window.color(b))));
	else return lerpColor(
		a,
		color(
			min(  red(window.color(a)),  red(window.color(b))),
			min(green(window.color(a)),green(window.color(b))),
			min( blue(window.color(a)), blue(window.color(b)))),
		opacity);
}

function maxColors(a,b,opacity) {
	if (!opacity) return color(
		max(  red(window.color(a)),  red(window.color(b))),
		max(green(window.color(a)),green(window.color(b))),
		max( blue(window.color(a)), blue(window.color(b))));
	else return lerpColor(
		a,
		color(
			max(  red(window.color(a)),  red(window.color(b))*opacity),
			max(green(window.color(a)),green(window.color(b))*opacity),
			max( blue(window.color(a)), blue(window.color(b))*opacity)),
		opacity);
}


